const start = Date.now();
let found = null, lastErr = null;
while (Date.now() - start < 120000) {
  try {
    const r = await searchTools("fetch url");
    const list = Array.isArray(r) ? r : [];
    found = list.find(t => /fetch/i.test(t.name));
    if (found) {
      try {
        const res = await tools[found.name]({url: "https://example.com"});
        var out = res;
        break;
      } catch (e) { lastErr = e.message; found = null; }
    }
  } catch (e) { lastErr = e.message; }
  await sleep(5000);
}
if (!found) throw new Error("fetch failed: " + lastErr);
let text = typeof out === "string" ? out : JSON.stringify(out);
const r = await $`wc -w <<'EOF_PAGE'
${{raw: ""}}${text.replace(/\$/g, "")}
EOF_PAGE`.text();
r.trim()

